const catalogSection=document.createElement('div');catalogSection.className='japan-airport-catalog';catalogSection.innerHTML=`<div class="actions"><input id="japan-airport-search" placeholder="空港名・空港コード・都道府県で検索" aria-label="日本の空港を検索"><span id="japan-airport-count"></span></div><div class="japan-airport-layout"><div class="japan-airport-list" id="japan-airport-list"></div><div id="japan-airport-detail"></div></div>`;
const airportForm=$('airport-master-list').parentNode;airportForm.insertBefore(catalogSection,airportForm.querySelector('.airport-register-form'));
let selectedJapanAirport='KIJ';
function renderJapanAirportList(){
 const query=$('japan-airport-search').value.trim().toLowerCase();const items=japanAirportCatalog.filter(a=>(a.name+' '+a.iata+' '+a.location).toLowerCase().includes(query));
 $('japan-airport-count').textContent=items.length+' / 97空港';
 $('japan-airport-list').innerHTML=items.map(a=>`<button class="japan-airport-row ${selectedJapanAirport===a.code?'selected':''}" data-japan-airport="${a.code}"><b>${esc(a.iata||'—')}</b><span>${esc(a.name)}</span><small>${Toki.airportChoices.from.includes(a.code)||Toki.airportChoices.to.includes(a.code)?'登録済':''}</small></button>`).join('');
}
function renderJapanAirportDetail(){const a=japanAirportCatalog.find(a=>a.code===selectedJapanAirport);if(!a)return;
 $('japan-airport-detail').innerHTML=`<h3>${esc(a.name)} <small>${esc(a.iata||'IATAコードなし')}</small></h3><dl><dt>所在地</dt><dd>${esc(a.location)}</dd><dt>運用時間・利用時間</dt><dd class="airport-hours">${esc(a.hours)}</dd><dt>滑走路長・幅</dt><dd>${esc(a.runway)}</dd>${a.notes?`<dt>備考</dt><dd>${esc(a.notes)}</dd>`:''}</dl><div class="airport-registration-state"><span>出発空港：${Toki.airportChoices.from.includes(a.code)?'登録済み':'未登録'}</span><span>到着空港：${Toki.airportChoices.to.includes(a.code)?'登録済み':'未登録'}</span></div><p class="airport-source"><a href="${a.source}" target="_blank" rel="noopener">出典資料を見る</a> ／ 確認日 ${a.checked}</p><div class="actions"><button id="japan-airport-register" class="primary">選択した空港を登録</button><button id="japan-airport-unregister">選択肢から外す</button></div>`;
 $('japan-airport-register').onclick=()=>registerJapanAirport(a.code);$('japan-airport-unregister').onclick=()=>unregisterJapanAirport(a.code);
}
function registerJapanAirport(code){
 const direction='both';
 const a=japanAirportCatalog.find(a=>a.code===code);if(!a)return;
 const previous={...airports},previousChoices=structuredClone(Toki.airportChoices),next={...airports,[code]:airports[code]||a.name},choices=structuredClone(Toki.airportChoices);
 for(const key of direction==='both'?['from','to']:[direction])if(!choices[key].includes(code))choices[key].push(code);
 try{localStorage.setItem('toki-airports-v1',JSON.stringify(next));localStorage.setItem('toki-airport-choices-v1',JSON.stringify(choices));}catch(e){try{localStorage.setItem('toki-airports-v1',JSON.stringify(previous));localStorage.setItem('toki-airport-choices-v1',JSON.stringify(previousChoices));}catch(ignore){}toast('空港を保存できませんでした。');return;}
 Object.assign(airports,next);Toki.airportChoices=choices;render();renderAirportMaster();renderAirportChoices();renderJapanAirportList();renderJapanAirportDetail();toast(a.name+'を登録しました。');
}
$('japan-airport-search').oninput=renderJapanAirportList;
$('japan-airport-list').onclick=e=>{const b=e.target.closest('[data-japan-airport]');if(!b)return;selectedJapanAirport=b.dataset.japanAirport;renderJapanAirportList();renderJapanAirportDetail();};
const showSettingsBeforeCatalog=showSettingsPage;showSettingsPage=function(show){showSettingsBeforeCatalog(show);if(show){renderJapanAirportList();renderJapanAirportDetail();}};
renderJapanAirportList();renderJapanAirportDetail();

function unregisterJapanAirport(code){
 const direction='both';
 const next=structuredClone(Toki.airportChoices),directions=direction==='both'?['from','to']:[direction];
 for(const key of directions){if(next[key].includes(code)&&next[key].length<=1){toast('出発・到着それぞれ1空港以上残してください。');return;}next[key]=next[key].filter(c=>c!==code);}
 try{localStorage.setItem('toki-airport-choices-v1',JSON.stringify(next));}catch(e){toast('保存できませんでした。');return;}
 Toki.airportChoices=next;render();renderAirportMaster();renderAirportChoices();renderJapanAirportList();renderJapanAirportDetail();toast('選択肢から外しました。作成済みの便はそのまま残ります。');
}

// Editable names retain stable IDs so existing events and maintenance checks stay intact.
const EVENT_CATEGORIES_KEY='toki-event-categories-v1';
let eventCategories=[{id:'maintenance',name:'重整備'},{id:'inspection',name:'点検・整備'},{id:'airworthiness',name:'耐空検査'},{id:'other',name:'その他'}],eventCategoryEditing='';
let eventCategoryWritable=true;
try{const raw=localStorage.getItem(EVENT_CATEGORIES_KEY);if(raw){const saved=JSON.parse(raw),ids=new Set();if(!Array.isArray(saved)||saved.length>100||saved.some(c=>!c||!['maintenance','inspection','airworthiness','other'].includes(c.id)&&!/^custom[a-z0-9]+$/.test(c.id||'')||typeof c.name!=='string'||!c.name.trim()||c.name.length>40||ids.has(c.id)||!ids.add(c.id)))throw Error('invalid');eventCategories=saved;}}catch(e){eventCategoryWritable=false;toast('保存済みイベント区分を読み込めません。既存データは上書きしません。');}
for(const event of aircraftEvents)if(!eventCategories.some(c=>c.id===event.type))eventCategories.push({id:event.type,name:({maintenance:'重整備',inspection:'点検・整備',airworthiness:'耐空検査',other:'その他'})[event.type]||'追加区分 '+event.type.slice(-4)});
const categorySettings=document.createElement('section');categorySettings.className='panel';categorySettings.id='event-category-settings';categorySettings.innerHTML='<div class="actions"><label>区分名 <input id="event-category-name" maxlength="40" placeholder="例：花火大会"></label><button id="event-category-save" class="primary">追加</button><button id="event-category-cancel" hidden>キャンセル</button></div><div id="event-category-list"></div>';$('settings-page').appendChild(categorySettings);makeSettingsFold(categorySettings,'event-categories','イベント区分');
function updateEventCategoryOptions(){const prior=$('event-type').value;$('event-type').innerHTML='<option value=""></option>'+eventCategories.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');$('event-type').value=eventCategories.some(c=>c.id===prior)?prior:'';}
function renderEventCategories(){
 $('event-category-list').innerHTML=eventCategories.map(c=>{const used=aircraftEvents.filter(e=>e.type===c.id).length;return `<div class="event-category-row"><strong>${esc(c.name)}</strong><span class="muted">${used?used+'件で使用中':''}</span><button data-category-edit="${esc(c.id)}">名前変更</button><button data-category-delete="${esc(c.id)}" ${used?'disabled title="使用中の区分は削除できません"':''}>削除</button></div>`;}).join('')||'<p class="muted">区分未登録</p>';
}
function clearEventCategoryForm(){eventCategoryEditing='';$('event-category-name').value='';$('event-category-save').textContent='追加';$('event-category-cancel').hidden=true;}
function persistEventCategories(next){if(!eventCategoryWritable){toast('保存済み区分の確認が必要なため変更できません。');return false;}try{localStorage.setItem(EVENT_CATEGORIES_KEY,JSON.stringify(next));eventCategories=next;updateEventCategoryOptions();renderEventCategories();return true;}catch(e){toast('イベント区分を保存できませんでした。');return false;}}
$('event-category-save').onclick=()=>{const name=$('event-category-name').value.trim();if(!name||name.length>40){toast('区分名を1〜40文字で入力してください。');return;}if(eventCategories.some(c=>c.id!==eventCategoryEditing&&c.name===name)){toast('同じ名前の区分が登録されています。');return;}if(!eventCategoryEditing&&eventCategories.length>=100){toast('区分は100件までです。');return;}const next=structuredClone(eventCategories);if(eventCategoryEditing)next.find(c=>c.id===eventCategoryEditing).name=name;else next.push({id:'custom'+Date.now().toString(36)+Math.random().toString(36).slice(2,7),name});if(persistEventCategories(next))clearEventCategoryForm();};
$('event-category-cancel').onclick=clearEventCategoryForm;
$('event-category-list').onclick=e=>{const edit=e.target.closest('[data-category-edit]'),del=e.target.closest('[data-category-delete]');if(edit){const category=eventCategories.find(c=>c.id===edit.dataset.categoryEdit);if(!category)return;eventCategoryEditing=category.id;$('event-category-name').value=category.name;$('event-category-save').textContent='更新';$('event-category-cancel').hidden=false;$('event-category-name').focus();}if(del){const id=del.dataset.categoryDelete;if(aircraftEvents.some(e=>e.type===id)){toast('使用中の区分は削除できません。');return;}if(persistEventCategories(eventCategories.filter(c=>c.id!==id))&&eventCategoryEditing===id)clearEventCategoryForm();}};
const categorySettingsLink=document.createElement('button');categorySettingsLink.type='button';categorySettingsLink.id='event-category-settings-open';categorySettingsLink.textContent='区分を設定';$('event-type').parentNode.appendChild(categorySettingsLink);categorySettingsLink.onclick=()=>{$('events-dialog').close();showSettingsPage(true);renderEventCategories();const fold=categorySettings.closest('details');if(fold)fold.open=true;categorySettings.scrollIntoView({block:'start',behavior:'smooth'});};
const showSettingsBeforeEventCategories=showSettingsPage;showSettingsPage=function(show){showSettingsBeforeEventCategories(show);if(show)renderEventCategories();};
updateEventCategoryOptions();renderEventCategories();

// Split code controls preserve the stable code string consumed by create/rename handlers.
function installPlanCodeDropdown(inputId,dialogId,saveId,renaming=false){
 const input=$(inputId),dialog=$(dialogId);input.type='hidden';
 const row=document.createElement('div');row.className='plan-code-dropdowns';row.innerHTML=`<label>アルファベット<select id="${inputId}-letter" aria-label="ダイヤコードのアルファベット">${Array.from({length:26},(_,i)=>String.fromCharCode(65+i)).map(l=>`<option value="${l}">${l}</option>`).join('')}</select></label><label>数字<select id="${inputId}-number" aria-label="ダイヤコードの数字"></select></label><span id="${inputId}-preview" class="code-dropdown-preview"></span>`;input.parentNode.insertBefore(row,input.nextSibling);
 const letter=$(inputId+'-letter'),number=$(inputId+'-number'),preview=$(inputId+'-preview');
 function usedCodes(){const self=renaming?planLibrary.items.find(p=>p.id===renamingPlanId):null,key=self?(self.seasonKey||self.data?.season?.key||''):seasonRange(Number($('season-year').value),pendingSeasonKind||calendarSeason().kind).key;return new Set(planLibrary.items.filter(p=>p.id!==self?.id&&(p.seasonKey||p.data?.season?.key||'')===key).map(p=>p.name));}
 function syncValue(){input.value=letter.value+number.value;preview.textContent=input.value;$(saveId).disabled=usedCodes().has(input.value);}
 function fillNumbers(wanted=''){
 const used=usedCodes(),values=['',...Array.from({length:1000},(_,i)=>String(i))];if(wanted&&!values.includes(wanted))values.push(wanted);
 number.innerHTML=values.map(n=>`<option value="${n}" ${used.has(letter.value+n)?'disabled':''}>${n===''?'なし':n}${used.has(letter.value+n)?'（使用済み）':''}</option>`).join('');
 number.value=!used.has(letter.value+wanted)?wanted:values.find(n=>!used.has(letter.value+n))??'';syncValue();
 }
 letter.onchange=()=>fillNumbers(number.value);number.onchange=syncValue;
 const originalShow=dialog.showModal.bind(dialog);dialog.showModal=function(){const match=/^([A-Z])([0-9]{0,3})$/.exec(input.value);letter.value=match?.[1]||'A';fillNumbers(match?.[2]||'');originalShow();letter.focus();};
 row.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();if(!$(saveId).disabled)$(saveId).onclick();}});
}
installPlanCodeDropdown('new-plan-name','create-plan-dialog','confirm-create-plan');
installPlanCodeDropdown('rename-plan-code','rename-plan-dialog','rename-plan-save',true);

Toki.newFlightAirports={from:'KIJ',to:'NGO'};
try{const saved=JSON.parse(localStorage.getItem('toki-new-flight-airports-v1')||'null');if(saved&&airports[saved.from]&&airports[saved.to]&&saved.from!==saved.to)Toki.newFlightAirports={from:saved.from,to:saved.to};}catch(e){}
function renderNewFlightAirports(){$('new-flight-from').innerHTML=airportOptions(Toki.newFlightAirports.from);$('new-flight-to').innerHTML=airportOptions(Toki.newFlightAirports.to);}
for(const [id,key] of [['new-flight-from','from'],['new-flight-to','to']])$(id).onchange=e=>{
 const next={...Toki.newFlightAirports,[key]:e.target.value};if(!airports[next.from]||!airports[next.to]||next.from===next.to){renderNewFlightAirports();toast('出発空港と到着空港は別の空港を選んでください。');return;}
 try{localStorage.setItem('toki-new-flight-airports-v1',JSON.stringify(next));Toki.newFlightAirports=next;}catch(e){renderNewFlightAirports();toast('初期空港を保存できませんでした。');}
};
renderNewFlightAirports();
